from __future__ import annotations

"""Apply the active price rules to a cart and produce a priced result.

The engine walks the rules the catalog hands back, applies every rule that is
eligible at the current running subtotal, and accumulates the discount. Each
applied rule's action lands on the subtotal left by the rules before it. The
priced result records which rules fired and the final amount.
"""

from discount_math import apply_action, discount_for_action, total_discount
from rule_catalog import RuleCatalog
from rule_eligibility import is_eligible
from rule_models import Cart, PriceRule


class PricingResult:
    def __init__(self, cart: Cart) -> None:
        self.cart_id = cart.cart_id
        self.base_subtotal_cents = cart.base_subtotal_cents
        self.final_subtotal_cents = cart.base_subtotal_cents
        self.applied_rule_ids: list[str] = []
        self.lines: list[dict[str, object]] = []

    def record(self, rule: PriceRule, before: int, discount: int, after: int) -> None:
        self.applied_rule_ids.append(rule.rule_id)
        self.lines.append(
            {
                "rule_id": rule.rule_id,
                "priority": rule.priority,
                "label": rule.label,
                "subtotal_before_cents": before,
                "discount_cents": discount,
                "subtotal_after_cents": after,
                "stop_further_rules": rule.stop_further_rules,
            }
        )

    def total_discount_cents(self) -> int:
        return total_discount(self.base_subtotal_cents, self.final_subtotal_cents)

    def applied_count(self) -> int:
        return len(self.applied_rule_ids)

    def as_dict(self) -> dict[str, object]:
        return {
            "cart_id": self.cart_id,
            "base_subtotal_cents": self.base_subtotal_cents,
            "final_subtotal_cents": self.final_subtotal_cents,
            "total_discount_cents": self.total_discount_cents(),
            "applied_rule_ids": list(self.applied_rule_ids),
            "lines": list(self.lines),
        }


class CartPricingEngine:
    def __init__(self, catalog: RuleCatalog) -> None:
        self._catalog = catalog

    @property
    def catalog(self) -> RuleCatalog:
        return self._catalog

    def price(self, cart: Cart) -> PricingResult:
        """Walk the rules and fold each eligible discount into the subtotal."""

        result = PricingResult(cart)
        running = cart.base_subtotal_cents

        for rule in self._catalog.ordered_rules():
            if not is_eligible(rule, cart, running):
                continue
            before = running
            discount = discount_for_action(running, rule.action)
            running = apply_action(running, rule.action)
            result.record(rule, before, discount, running)

        result.final_subtotal_cents = running
        return result

    def quote_total(self, cart: Cart) -> int:
        return self.price(cart).final_subtotal_cents

    def applied_rule_ids(self, cart: Cart) -> list[str]:
        return self.price(cart).applied_rule_ids


def price_cart(catalog: RuleCatalog, cart: Cart) -> dict[str, object]:
    """One-shot helper: price a cart and return the plain-dict result."""

    return CartPricingEngine(catalog).price(cart).as_dict()


def summarize_pricing(results: list[PricingResult]) -> dict[str, object]:
    """Roll up a batch of priced carts for promo reporting."""

    total_base = sum(r.base_subtotal_cents for r in results)
    total_final = sum(r.final_subtotal_cents for r in results)
    return {
        "cart_count": len(results),
        "total_base_cents": total_base,
        "total_final_cents": total_final,
        "total_discount_cents": max(0, total_base - total_final),
        "carts": [r.as_dict() for r in results],
    }


def first_applied_rule_id(result: PricingResult) -> str | None:
    return result.applied_rule_ids[0] if result.applied_rule_ids else None


def rule_was_applied(result: PricingResult, rule_id: str) -> bool:
    return rule_id in result.applied_rule_ids

