from __future__ import annotations

"""Pure money math for discount actions, in integer cents.

Percent discounts round to the nearest cent. Fixed discounts subtract a flat
amount. Any single application is capped at the current subtotal so the
running total never drops below zero.
"""

from rule_models import DiscountAction


def percent_discount_cents(subtotal_cents: int, percent: int) -> int:
    """Cents removed by a percent-off action on ``subtotal_cents``."""

    if subtotal_cents < 0:
        raise ValueError("subtotal_cents must be non-negative")
    if percent < 0 or percent > 100:
        raise ValueError("percent must be between 0 and 100")
    raw = subtotal_cents * percent / 100
    discount = int(round(raw))
    return min(discount, subtotal_cents)


def fixed_discount_cents(subtotal_cents: int, amount_cents: int) -> int:
    """Cents removed by a fixed-amount action, never more than the subtotal."""

    if subtotal_cents < 0:
        raise ValueError("subtotal_cents must be non-negative")
    if amount_cents < 0:
        raise ValueError("amount_cents must be non-negative")
    return min(amount_cents, subtotal_cents)


def discount_for_action(subtotal_cents: int, action: DiscountAction) -> int:
    """Cents removed by applying ``action`` to ``subtotal_cents``."""

    if action.kind == "percent":
        return percent_discount_cents(subtotal_cents, action.amount)
    if action.kind == "fixed":
        return fixed_discount_cents(subtotal_cents, action.amount)
    raise ValueError(f"unsupported action kind: {action.kind}")


def apply_action(subtotal_cents: int, action: DiscountAction) -> int:
    """Return the new subtotal after applying ``action`` once.

    The result is clamped at zero; a discount can take the cart to free but
    never negative.
    """

    discount = discount_for_action(subtotal_cents, action)
    new_subtotal = subtotal_cents - discount
    return max(0, new_subtotal)


def clamp_non_negative(cents: int) -> int:
    return max(0, cents)


def total_discount(base_cents: int, final_cents: int) -> int:
    """Total cents removed between the base and final subtotal."""

    return clamp_non_negative(base_cents - clamp_non_negative(final_cents))


def effective_percent(base_cents: int, final_cents: int) -> float:
    if base_cents <= 0:
        return 0.0
    removed = total_discount(base_cents, final_cents)
    return round(removed / base_cents * 100, 4)


def describe_action(subtotal_cents: int, action: DiscountAction) -> dict[str, object]:
    discount = discount_for_action(subtotal_cents, action)
    return {
        "kind": action.kind,
        "amount": action.amount,
        "subtotal_before_cents": subtotal_cents,
        "discount_cents": discount,
        "subtotal_after_cents": clamp_non_negative(subtotal_cents - discount),
    }


def money_label(cents: int, currency: str = "USD") -> str:
    major = clamp_non_negative(cents) / 100
    return f"{major:.2f} {currency.upper()}"

