from __future__ import annotations

"""Storage for the active set of cart price rules.

Rules are added to the catalog as the merchant configures promotions, in no
particular order. The pricing engine asks the catalog for the rules to walk;
that walk order is what determines which rule gets the first crack at the
subtotal.
"""

from rule_models import DiscountAction, PriceRule, build_rule


class RuleCatalog:
    def __init__(self, rules: list[PriceRule] | None = None) -> None:
        self._rules: list[PriceRule] = []
        for rule in rules or []:
            self.add(rule)

    def add(self, rule: PriceRule) -> PriceRule:
        if any(existing.rule_id == rule.rule_id for existing in self._rules):
            raise ValueError(f"duplicate rule_id: {rule.rule_id}")
        self._rules.append(rule)
        return rule

    def remove(self, rule_id: str) -> None:
        self._rules = [rule for rule in self._rules if rule.rule_id != rule_id]

    def get(self, rule_id: str) -> PriceRule | None:
        for rule in self._rules:
            if rule.rule_id == rule_id:
                return rule
        return None

    def all_rules(self) -> list[PriceRule]:
        """Every configured rule, in the order it was added."""

        return list(self._rules)

    def ordered_rules(self) -> list[PriceRule]:
        """The rules in the order the engine should evaluate them."""

        return list(self._rules)

    def priorities(self) -> list[int]:
        return [rule.priority for rule in self.ordered_rules()]

    def rule_ids_in_order(self) -> list[str]:
        return [rule.rule_id for rule in self.ordered_rules()]

    def count(self) -> int:
        return len(self._rules)

    def is_empty(self) -> bool:
        return not self._rules

    def coupon_rules(self) -> list[PriceRule]:
        return [rule for rule in self._rules if rule.is_coupon_gated()]

    def has_rule(self, rule_id: str) -> bool:
        return any(rule.rule_id == rule_id for rule in self._rules)

    def __len__(self) -> int:
        return len(self._rules)

    def __contains__(self, rule_id: object) -> bool:
        return isinstance(rule_id, str) and self.has_rule(rule_id)


def build_seed_catalog() -> RuleCatalog:
    """A representative promo set, deliberately added out of priority order.

    Priorities are 10, 20, 30, 40. They are not added in that sequence, which
    is normal: merchants toggle promotions on as campaigns launch.
    """

    catalog = RuleCatalog()
    catalog.add(
        build_rule(
            rule_id="loyalty_fixed",
            priority=30,
            action=DiscountAction(kind="fixed", amount=500),
            min_subtotal_cents=2_000,
            label="Loyalty $5 off",
        )
    )
    catalog.add(
        build_rule(
            rule_id="welcome_percent",
            priority=10,
            action=DiscountAction(kind="percent", amount=20),
            stop_further_rules=True,
            label="Welcome 20% (exclusive)",
        )
    )
    catalog.add(
        build_rule(
            rule_id="coupon_save15",
            priority=20,
            action=DiscountAction(kind="percent", amount=15),
            required_coupon="SAVE15",
            label="SAVE15 coupon",
        )
    )
    catalog.add(
        build_rule(
            rule_id="clearance_fixed",
            priority=40,
            action=DiscountAction(kind="fixed", amount=1_000),
            min_subtotal_cents=5_000,
            label="Clearance $10 off",
        )
    )
    return catalog

