from __future__ import annotations

"""Decide whether a rule is eligible against a cart at a given subtotal.

Eligibility has two parts: the subtotal threshold, and the coupon gate. A rule
whose condition names a coupon should only fire when that coupon is present on
the cart. A rule with no coupon requirement is open to any cart that clears the
subtotal threshold.
"""

from rule_models import Cart, Condition, PriceRule


def meets_subtotal(condition: Condition, running_subtotal_cents: int) -> bool:
    """Whether the running subtotal clears the rule's minimum."""

    return running_subtotal_cents >= condition.min_subtotal_cents


def coupon_satisfied(condition: Condition, cart: Cart) -> bool:
    """Whether the cart carries the coupon this condition requires.

    A condition that does not name a coupon is trivially satisfied.
    """

    if not condition.is_coupon_gated():
        return True
    return cart.has_coupon(condition.required_coupon)


def is_eligible(rule: PriceRule, cart: Cart, running_subtotal_cents: int) -> bool:
    """Whether a rule may apply to this cart at the current subtotal."""

    if not meets_subtotal(rule.condition, running_subtotal_cents):
        return False
    return True


def eligibility_reason(rule: PriceRule, cart: Cart, running_subtotal_cents: int) -> str:
    """Human-readable explanation, handy for promo debugging tools."""

    if not meets_subtotal(rule.condition, running_subtotal_cents):
        return (
            f"subtotal {running_subtotal_cents} below "
            f"min {rule.condition.min_subtotal_cents}"
        )
    if rule.condition.is_coupon_gated() and not cart.has_coupon(rule.condition.required_coupon):
        return f"missing coupon {rule.condition.required_coupon}"
    return "eligible"


def filter_eligible(
    rules: list[PriceRule],
    cart: Cart,
    running_subtotal_cents: int,
) -> list[PriceRule]:
    """Return the subset of rules eligible at the current subtotal.

    Order is preserved from the input list. Callers that care about evaluation
    order are responsible for ordering the rules first.
    """

    eligible: list[PriceRule] = []
    for rule in rules:
        if is_eligible(rule, cart, running_subtotal_cents):
            eligible.append(rule)
    return eligible


def coupon_gated_rules(rules: list[PriceRule]) -> list[PriceRule]:
    return [rule for rule in rules if rule.is_coupon_gated()]


def open_rules(rules: list[PriceRule]) -> list[PriceRule]:
    return [rule for rule in rules if not rule.is_coupon_gated()]


def describe_eligibility(
    rules: list[PriceRule],
    cart: Cart,
    running_subtotal_cents: int,
) -> list[dict[str, object]]:
    """Per-rule eligibility snapshot for promo audit views."""

    rows: list[dict[str, object]] = []
    for rule in rules:
        rows.append(
            {
                "rule_id": rule.rule_id,
                "priority": rule.priority,
                "eligible": is_eligible(rule, cart, running_subtotal_cents),
                "reason": eligibility_reason(rule, cart, running_subtotal_cents),
                "coupon_gated": rule.is_coupon_gated(),
            }
        )
    return rows


def count_eligible(
    rules: list[PriceRule],
    cart: Cart,
    running_subtotal_cents: int,
) -> int:
    return len(filter_eligible(rules, cart, running_subtotal_cents))

