    return [rule for rule in rules if rule.is_coupon_gated()]


def open_rules(rules: list[PriceRule]) -> list[PriceRule]:
    return [rule for rule in rules if not rule.is_coupon_gated()]


def describe_eligibility(
    rules: list[PriceRule],
    cart: Cart,
    running_subtotal_cents: int,
) -> list[dict[str, object]]:
    """Per-rule eligibility snapshot for promo audit views."""

    rows: list[dict[str, object]] = []
    for rule in rules:
        rows.append(
            {
                "rule_id": rule.rule_id,
                "priority": rule.priority,
                "eligible": is_eligible(rule, cart, running_subtotal_cents),
                "reason": eligibility_reason(rule, cart, running_subtotal_cents),
                "coupon_gated": rule.is_coupon_gated(),
            }
        )
    return rows


def count_eligible(
    rules: list[PriceRule],
    cart: Cart,
    running_subtotal_cents: int,
) -> int:
    return len(filter_eligible(rules, cart, running_subtotal_cents))

