and a ``stop_further_rules`` flag. Money is always integer cents.
"""

from dataclasses import dataclass, field


def _require_label(label: str, value: str | None) -> str:
    if value is None or not str(value).strip():
        raise ValueError(f"{label} is required")
    return str(value).strip()


@dataclass(frozen=True)
class Condition:
    """What a cart must satisfy for a rule to be eligible.

    ``min_subtotal_cents`` is checked against the cart's running subtotal.
    ``required_coupon`` (when set) gates the rule behind a coupon code that the
    cart must carry. A condition with neither field set always matches.
    """

    min_subtotal_cents: int = 0
    required_coupon: str | None = None

    def __post_init__(self) -> None:
        if self.min_subtotal_cents < 0:
            raise ValueError("min_subtotal_cents must be non-negative")
        if self.required_coupon is not None:
            coupon = _require_label("required_coupon", self.required_coupon)
            object.__setattr__(self, "required_coupon", coupon.upper())

    def is_coupon_gated(self) -> bool:
        return self.required_coupon is not None


@dataclass(frozen=True)
class DiscountAction:
    """How much to subtract from the running subtotal.

    ``kind`` is ``"percent"`` (``amount`` is whole percent points, 0-100) or
    ``"fixed"`` (``amount`` is cents to remove).
    """

    kind: str
    amount: int

    def __post_init__(self) -> None:
        kind = _require_label("kind", self.kind).lower()
        if kind not in {"percent", "fixed"}:
            raise ValueError("kind must be 'percent' or 'fixed'")
        if self.amount < 0:
            raise ValueError("amount must be non-negative")
        if kind == "percent" and self.amount > 100:
            raise ValueError("percent amount cannot exceed 100")
        object.__setattr__(self, "kind", kind)


@dataclass(frozen=True)
class PriceRule:
    rule_id: str
    priority: int
    condition: Condition
    action: DiscountAction
    stop_further_rules: bool = False
    label: str = ""

    def __post_init__(self) -> None:
        rid = _require_label("rule_id", self.rule_id)
        object.__setattr__(self, "rule_id", rid)
        if not self.label:
            object.__setattr__(self, "label", rid)

    def is_coupon_gated(self) -> bool:
        return self.condition.is_coupon_gated()


@dataclass
class Cart:
    """A shopping cart with a base subtotal and any coupon codes applied."""

    cart_id: str
    base_subtotal_cents: int
    coupons: list[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        self.cart_id = _require_label("cart_id", self.cart_id)
        if self.base_subtotal_cents < 0:
            raise ValueError("base_subtotal_cents must be non-negative")
        self.coupons = [str(c).strip().upper() for c in self.coupons if str(c).strip()]

    def has_coupon(self, code: str | None) -> bool:
        if code is None:
            return False
        return code.strip().upper() in self.coupons


def build_rule(
    *,
    rule_id: str,
    priority: int,
    action: DiscountAction,
    min_subtotal_cents: int = 0,
    required_coupon: str | None = None,
    stop_further_rules: bool = False,
    label: str = "",
) -> PriceRule:
    """Convenience constructor used by tests and seed data."""

    condition = Condition(
        min_subtotal_cents=min_subtotal_cents,
        required_coupon=required_coupon,
    )
    return PriceRule(
        rule_id=rule_id,
        priority=priority,
        condition=condition,
        action=action,
        stop_further_rules=stop_further_rules,
        label=label,
    )


def percent_off(percent: int) -> DiscountAction:
    return DiscountAction(kind="percent", amount=percent)


def fixed_off(cents: int) -> DiscountAction:
    return DiscountAction(kind="fixed", amount=cents)


def build_cart(
    *,
    cart_id: str = "cart_demo",
    base_subtotal_cents: int,
    coupons: list[str] | None = None,
) -> Cart:
    return Cart(
        cart_id=cart_id,
        base_subtotal_cents=base_subtotal_cents,
        coupons=list(coupons or []),
    )

